#include <ocpp/v16/known_keys_yaml.hpp>

#include <ocpp/v16/known_keys.hpp>

#include <ryml.hpp>
#include <ryml_std.hpp>

namespace ocpp::v16::keys {

namespace {

#define VALUE(a, b) valid_keys::b,
constexpr valid_keys all_keys[] = {FOR_ALL_KEYS(VALUE)};
#undef VALUE

constexpr const char* header = R"(# Built-in OCPP 1.6 configuration key to OCPP 2.x Component/Variable mappings.
# Generated by ocpp16_default_mappings_generator from ocpp/v16/known_keys.hpp. Do not edit.
# Reference only: this is not a custom mapping file for DeviceModelConfigMappings.
)";

c4::csubstr to_csubstr(const std::string_view& str) {
    return {str.data(), str.size()};
}

void add_key(ryml::NodeRef node, valid_keys key) {
    node |= ryml::MAP;
    node["ocpp16_key"] << to_csubstr(convert(key));
    node["section"] << to_csubstr(to_section_string_view(key));
}

void add_mapping(ryml::NodeRef node, valid_keys key, const ocpp::v2::Component& component,
                 const ocpp::v2::Variable& variable) {
    add_key(node, key);

    auto component_node = node["component"];
    component_node |= ryml::MAP;
    component_node["name"] << component.name.get();
    if (component.instance.has_value()) {
        component_node["instance"] << component.instance->get();
    }
    if (component.evse.has_value()) {
        auto evse_node = component_node["evse"];
        evse_node |= ryml::MAP;
        evse_node["id"] << component.evse->id;
        if (component.evse->connectorId.has_value()) {
            evse_node["connectorId"] << component.evse->connectorId.value();
        }
    }

    auto variable_node = node["variable"];
    variable_node |= ryml::MAP;
    variable_node["name"] << variable.name.get();
    if (variable.instance.has_value()) {
        variable_node["instance"] << variable.instance->get();
    }

    node["target"] << (is_max_limit_key(key) ? "maxLimit" : "Actual");
}

} // namespace

std::string default_mappings_to_yaml() {
    ryml::Tree tree;
    auto root = tree.rootref();
    root |= ryml::MAP;
    auto mappings = root["mappings"];
    mappings |= ryml::SEQ;
    auto unmapped_keys = root["unmapped_keys"];
    unmapped_keys |= ryml::SEQ;

    for (const auto key : all_keys) {
        if (const auto cv = convert_v2(key)) {
            add_mapping(mappings.append_child(), key, cv->first, cv->second);
        } else {
            add_key(unmapped_keys.append_child(), key);
        }
    }

    return header + ryml::emitrs_yaml<std::string>(tree);
}

} // namespace ocpp::v16::keys
